    // Manejo de errores sintácticos comunes
    @Override
    public void syntax_error(Symbol s){
        this.s = s;
        String mensaje = " Error de sintaxis en línea " + (s.right + 1) + 
                         ", columna " + (s.left + 1) + ". ";
        
        if(s.value != null){
            mensaje += "Token inesperado: '" + s.value + "'. ";
        }

        // Posibles causas comunes
        mensaje += sugerirCorreccion(s);

        resultado += mensaje + "\n";
        System.err.println(mensaje);
    }

    // Método de apoyo para dar sugerencias claras
    private String sugerirCorreccion(Symbol s){
        String token = (s.value != null) ? s.value.toString() : "";

        if(token.matches("[0-9]+[a-zA-Z]+")) {
            return "Posible error: mezcla de número y letra sin reglas claras. " +
                   "Revisa la definición de identificadores.";
        }
        if(token.equalsIgnoreCase("inicio:")) {
            return "¿Falta 'FINAL' o estructura incorrecta? Revisa la estructura del programa.";
        }
        if(token.trim().isEmpty()){
            return "Espacio o símbolo vacío no reconocido.";
        }
        return "Revisa el orden y la estructura de la expresión.";
    }

    // Cuando ocurre un error grave y no se puede continuar
    @Override
    public void unrecovered_syntax_error(Symbol s) throws java.lang.Exception {
        throw new RuntimeException(" Error sintáctico irrecuperable en línea " 
                                    + (s.right + 1) + ", columna " 
                                    + (s.left + 1));
    }

    // Reporte de errores genéricos
    @Override
    public void report_error(String message, Object info) {
        resultado += "" + message + " -> " + info + "\n";
        System.err.println("" + message + " -> " + info);
    }

    // Método para registrar producciones (opcional para depuración)
    private void logProduccion(String produccion) {
        resultado += "Producción aplicada: " + produccion + "\n";
    }


